def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n >= 99:
        return 'D'
    if history[-1][0] == 'C' and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'

    opp_c = 0
    for _m, o in history:
        if o == 'C':
            opp_c += 1

    cnt = [0, 0, 0, 0]
    dcnt = [0, 0, 0, 0]
    rcnt = [0, 0, 0, 0]
    rdcnt = [0, 0, 0, 0]

    start = n - 21
    if start < 0:
        start = 0

    for i in range(n - 1):
        m, o = history[i]
        if m == 'C':
            idx = 0 if o == 'C' else 1
        else:
            idx = 2 if o == 'C' else 3

        opp_now = history[i + 1][1]
        if opp_now == 'D':
            dcnt[idx] += 1
        cnt[idx] += 1

        if i >= start:
            if opp_now == 'D':
                rdcnt[idx] += 1
            rcnt[idx] += 1

    bias = [0.10, 0.20, 0.55, 0.60]
    T = []
    for i in range(4):
        p_tot = (dcnt[i] + bias[i] * 2.0) / (cnt[i] + 2.0)
        if rcnt[i] > 0:
            p_rec = (rdcnt[i] + bias[i] * 1.0) / (rcnt[i] + 1.0)
        else:
            p_rec = p_tot
        T.append(0.65 * p_tot + 0.35 * p_rec)

    lm, lo = history[-1]
    if lm == 'C':
        if lo == 'C':
            s0 = 0
        else:
            s0 = 1
    else:
        if lo == 'C':
            s0 = 2
        else:
            s0 = 3

    K = 100 - n
    if K > 20:
        K = 20

    v0 = v1 = v2 = v3 = 0.0
    choice = [0, 0, 0, 0]

    for _ in range(K):
        p = T[0]
        pc = 1.0 - p
        c0 = pc * (3.0 + v0) + p * (0.0 + v1)
        d0 = pc * (5.0 + v2) + p * (1.0 + v3)
        if c0 >= d0:
            n0 = c0
            ch0 = 0
        else:
            n0 = d0
            ch0 = 1

        p = T[1]
        pc = 1.0 - p
        c1 = pc * (3.0 + v0) + p * (0.0 + v1)
        d1 = pc * (5.0 + v2) + p * (1.0 + v3)
        if c1 >= d1:
            n1 = c1
            ch1 = 0
        else:
            n1 = d1
            ch1 = 1

        p = T[2]
        pc = 1.0 - p
        c2 = pc * (3.0 + v0) + p * (0.0 + v1)
        d2 = pc * (5.0 + v2) + p * (1.0 + v3)
        if c2 >= d2:
            n2 = c2
            ch2 = 0
        else:
            n2 = d2
            ch2 = 1

        p = T[3]
        pc = 1.0 - p
        c3 = pc * (3.0 + v0) + p * (0.0 + v1)
        d3 = pc * (5.0 + v2) + p * (1.0 + v3)
        if c3 >= d3:
            n3 = c3
            ch3 = 0
        else:
            n3 = d3
            ch3 = 1

        v0 = n0
        v1 = n1
        v2 = n2
        v3 = n3
        choice = [ch0, ch1, ch2, ch3]

    act = choice[s0]
    r = rng.random()

    if s0 == 3 and opp_c == 0 and n <= 30:
        act = 1

    if act == 1:
        if s0 == 0:
            if T[2] >= 0.50 and r >= 0.02:
                act = 0
        elif s0 == 2:
            if T[2] >= 0.55 and r >= 0.10:
                act = 0
        elif s0 == 3:
            if opp_c > 0 and T[1] < 0.72:
                if r < 0.20:
                    act = 0
            elif opp_c == 0 and n >= 30 and T[1] < 0.72:
                if r < 0.05:
                    act = 0
            else:
                if r < 0.01:
                    act = 0
        elif s0 == 1:
            if opp_c >= max(1, int(0.15 * n)) and T[1] < 0.62 and T[0] < 0.48:
                if r < 0.70:
                    act = 0
    else:
        if s0 == 0 and n < 92:
            probe_p = 0.065 if opp_c >= max(4, int(0.75 * n)) else 0.025
            if r < probe_p:
                act = 1
        elif s0 == 1 and n < 95:
            if opp_c >= max(2, int(0.35 * n)) and r < 0.02:
                act = 1

    if act == 1:
        return 'D'
    return 'C'
